input.command:
SESS=session_2026-09-18-research-batch-16-backward-mining-t2-anchors && DSHA=$(git log -1 --format=%h -- governance/ references/project-standards.md CLAUDE.md) && echo "doctrine_sha: $DSHA" && cat > "attestations/sessions_$SESS.json" <<EOF
{
  "schema_version": "1.0",
  "session": "$SESS",
  "artifact": "sessions/$SESS.md",
  "doctrine_sha": "$DSHA",
  "rules_in_scope": [
    "adherence-logging-and-attestation",
    "source-discipline",
    "integrity-protocol",
    "multilingual-research"
  ],
  "per_rule_status": {
    "adherence-logging-and-attestation": {
      "status": "FIRED",
      "evidence_path": "scratchpad/$SESS/priors.md",
      "reason": "Priors for all five units were committed at 589577b BEFORE the first query ran, and they are falsifiable rather than decorative: each names an expected yield and the batch's premise section states outright what would falsify it. Three of the five were then WRONG, two of them badly, and the record says so in the search rows, the mining register and section 4 of the session record rather than in a footnote. The prior on REF-00985 predicted zero relevant references against 23 of 46 actual -- the single largest miss -- and it is the one that carried the batch, so there is no reading on which the errors are incidental to the result."
    },
    "source-discipline": {
      "status": "FIRED",
      "evidence_path": "retrieval-log/$SESS/manifest.jsonl",
      "reason": "A search-engine summary returned a specific, plausible 1:12 / 8.3 per cent figure attributed to Swedish DPO guidance. It is recorded NOWHERE -- not as a candidate value, not in a note -- and the search row says why: a model-generated synthesis with no retrieved document behind it is the CLAUDE.md 5(c) shape. Every one of the seven claim texts written this batch was verified as a byte-exact substring of a persisted artefact before the extraction was attempted, and the TRID abstract was re-fetched through retrieval_log specifically so the 7 per cent figure would rest on persisted bytes rather than on a WebFetch summary. ref_id= was passed on every fetch(), which GAP-012 records as regressed across batches 10-15."
    },
    "integrity-protocol": {
      "status": "FIRED",
      "evidence_path": "sessions/$SESS.md",
      "reason": "The batch found the anchoring-tier stated maximum six batches of searching had missed, and then DECLINED TO USE IT. Extraction 45 is skim/preliminary because the article was not retrieved -- only its TRID record -- and the cell was left at 5 per cent with determination gate 1 raised instead of being re-determined at 7. The refusal cost the batch its headline and follows batch 15's precedent on REF-01001, where the same caution was vindicated by the full text. Two writer defects found by using the write path were fixed at source rather than worked around, and the discharged deferral text was carried into notes rather than destroyed, per the 2026-09-16 retire-in-place ruling."
    },
    "multilingual-research": {
      "status": "FIRED",
      "evidence_path": "retrieval-log/$SESS/manifest.jsonl",
